//! Custom icon pack generated by build.rs, merged with the bundled Phosphor Regular set.
//!
//! Options: `--size WxH`, `--light`.

use eframe::egui;
use egui_icon_pack::phosphor_regular as bundled;
use egui_icon_pack::{IconPack, IconRegistry, gallery, widgets};

#[allow(dead_code)]
mod icons {
    include!(concat!(env!("OUT_DIR"), "/icon_table.rs"));
}

struct App {
    registry: IconRegistry,
    pressed: u32,
    pinned: bool,
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        egui::Panel::left("custom_pack_example.usage")
            .default_size(230.0)
            .show(ui, |ui| {
                widgets::heading(ui, icons::DEMO_ORBIT, "Custom pack");
                ui.weak(format!(
                    "{} generated icons, {} merged with Phosphor",
                    icons::ALL.len(),
                    self.registry.len()
                ));
                ui.separator();
                for icon in icons::ALL {
                    ui.horizontal(|ui| {
                        icon.show(ui, 28.0);
                        ui.monospace(format!("icons::{}", icon.const_name()));
                    });
                }
                ui.separator();
                if widgets::button(ui, icons::DEMO_STACK, "Press").clicked() {
                    self.pressed += 1;
                }
                if widgets::selectable_button(ui, icons::DEMO_SIGNAL, self.pinned, "Pinned")
                    .clicked()
                {
                    self.pinned = !self.pinned;
                }
                ui.label(format!(
                    "pressed {} times, pinned: {}",
                    self.pressed, self.pinned
                ));
                ui.separator();
                let source = if self.registry.find("star") == Some(icons::STAR) {
                    "custom pack"
                } else {
                    "bundled pack"
                };
                ui.weak(format!("registry resolves star from the {source}"));
                ui.weak(format!("bundled pack has {} icons", bundled::ALL.len()));
            });
        egui::CentralPanel::default().show(ui, |ui| gallery::show(ui, &self.registry));
    }
}

fn main() -> eframe::Result {
    let args: Vec<String> = std::env::args().collect();
    let size = args
        .iter()
        .position(|a| a == "--size")
        .and_then(|i| args.get(i + 1))
        .and_then(|s| s.split_once('x'))
        .and_then(|(w, h)| Some([w.parse::<f32>().ok()?, h.parse::<f32>().ok()?]))
        .unwrap_or([980.0, 640.0]);
    let light = args.iter().any(|a| a == "--light");

    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default().with_inner_size(size),
        ..Default::default()
    };
    eframe::run_native(
        "Custom icon pack",
        options,
        Box::new(move |cc| {
            let mut fonts = egui::FontDefinitions::default();
            egui_icon_pack::install_fonts(&mut fonts);
            cc.egui_ctx.set_fonts(fonts);
            egui_icon_pack::install(&cc.egui_ctx);
            cc.egui_ctx.set_theme(if light {
                egui::Theme::Light
            } else {
                egui::Theme::Dark
            });
            let registry = IconRegistry::new().with(&icons::PACK).with(&bundled::PACK);
            Ok(Box::new(App {
                registry,
                pressed: 0,
                pinned: false,
            }))
        }),
    )
}
